import{_ as p,o as t,c as e,a2 as s}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/quesion_imgs_5d2931a2a48043a19f20e9e27662c167.w06KxreO.png",i="/bzygq/assets/quesion_imgs_d8c882c3f75e47c6b748249c73e28110.BM2zmLli.png",o="/bzygq/assets/quesion_imgs_79d4d27270934ad48335659bdc32bb22.VBHDH6e0.png",n="/bzygq/assets/quesion_imgs_0c1676f7759447829ffd115251bf3018.CdbC8RFf.png",l="/bzygq/assets/quesion_imgs_5a41132cf7254e428a4b1796d3405dad.CHAlKzCQ.png",c="/bzygq/assets/quesion_imgs_e54e0183098745828e66b31ce4c73e56.BnPbRS0a.png",_="/bzygq/assets/quesion_imgs_c0e1121bf9764d0987797bd65dc20e58.C-L1jRLi.png",d="/bzygq/assets/quesion_imgs_953ccf5f00a14d2ebf19b2f6d32d51c9.CKlhwxuF.png",g="/bzygq/assets/quesion_imgs_8765e3b7753f41feb53f87e5a0dbcf02.BcbsYVaJ.png",m="/bzygq/assets/quesion_imgs_42e4c873c0a34e7480ac7b93ac6aa18a.D-9sGMa3.png",z=JSON.parse('{"title":"功能元素的定义及作用","description":"","frontmatter":{},"headers":[],"relativePath":"行测/逻辑推理/1.图形推理/9.功能元素.md","filePath":"行测/逻辑推理/1.图形推理/9.功能元素.md","lastUpdated":1788883925000}'),h={name:"行测/逻辑推理/1.图形推理/9.功能元素.md"};function b(u,a,q,f,B,A){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="功能元素的定义及作用" tabindex="-1">功能元素的定义及作用 <a class="header-anchor" href="#功能元素的定义及作用" aria-label="Permalink to &quot;功能元素的定义及作用&quot;">​</a></h1><p><img src="'+r+'" alt=""></p><p>功能元素是指在图形中具有特定指示意义的符号，如黑点、白点、箭头等，功能元素主要用于标记图形中的特定位置、特征或关系，帮助理解图形的结构和逻辑。</p><p>常见考法：标记交点、标记边（封闭图形<a href="https://zhida.zhihu.com/search?content_id=234839459&amp;content_type=Article&amp;match_order=1&amp;q=%E6%9C%80%E9%95%BF%E8%BE%B9&amp;zhida_source=entity" target="_blank" rel="noreferrer">最长边</a>、最短边）、标记角的类型、标记位置（<a href="https://zhida.zhihu.com/search?content_id=234839459&amp;content_type=Article&amp;match_order=1&amp;q=%E7%9B%B8%E4%BA%A4%E5%8C%BA%E5%9F%9F&amp;zhida_source=entity" target="_blank" rel="noreferrer">相交区域</a>），箭头线的位置关系等。</p><p>如图1中①②的黑点分别标记其所在三角形的最长边和最短边，也可以分别标记其所在三角形的左边和右边、角(直角、锐角或钝角，如图 2，黑点标记的都是锐角、相交或非相交区域，如图 3，①的黑点标记非相交区域，②的黑点标记相交区域等。</p><h1 id="常见功能元素的使用场景" tabindex="-1">常见功能元素的使用场景 <a class="header-anchor" href="#常见功能元素的使用场景" aria-label="Permalink to &quot;常见功能元素的使用场景&quot;">​</a></h1><h2 id="标记位置" tabindex="-1">标记位置 <a class="header-anchor" href="#标记位置" aria-label="Permalink to &quot;标记位置&quot;">​</a></h2><p>【</p><ul><li>长/短边：标记图形中最长或最短的一边。</li><li>左/右位置：标记图形的左侧或右侧。</li><li>上下位置：标记图形的上方或下方。内外位置：标记图形的内部或外部。 】</li></ul><p><strong>例题：</strong> 把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src="'+i+'" alt=""></p><p>A.①③④，②⑤⑥</p><p>B.①③⑥，②④⑤</p><p>C.①②③，④⑤⑥</p><p>D.①③⑤，②④⑥</p><p><strong>解析：</strong> 考查标记元素的标记最大角最小角；每个小白球都挨着三角形的一个角，观察发现，①③④中小白球挨着的是三角形中最大的角，②⑤⑥中小白球挨着的是三角形中最小的角。即①③④一组，②⑤⑥一组。故正确答案为A。</p><h2 id="标记角度" tabindex="-1">标记角度 <a class="header-anchor" href="#标记角度" aria-label="Permalink to &quot;标记角度&quot;">​</a></h2><p>【</p><ul><li>直角：标记直角。</li><li>锐角：标记锐角。</li><li>钝角：标记钝角。 】</li></ul><p><strong>例题：</strong> 从所给的四个选项中，选择最合适的一项填在问号处，使之呈现一定的规律性：</p><p><img src="'+o+'" alt=""></p><p><strong>解析：</strong> 观察上图发现所有黑点都仅出现在图形的锐角处，A、B 两项存在直角处小黑点，C 项存在钝角处小黑点，排除 A、B、C 三项。故正确答案为D。</p><h2 id="标记区域" tabindex="-1">标记区域 <a class="header-anchor" href="#标记区域" aria-label="Permalink to &quot;标记区域&quot;">​</a></h2><p>【 相交区域：标记图形中相交的部分。 非相交区域：标记图形中不相交的部分。 】</p><p><strong>例题：</strong> 把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src="'+n+'" alt=""></p><p>A.①⑤⑥，②③④</p><p>B.①③④，②⑤⑥</p><p>C.①②④，③⑤⑥</p><p>D.①②⑤，③④⑥</p><p><strong>解析：</strong> 考查标记点的位置；①③④中的黑点不在图形的相交区域内，②⑤⑥中的黑点则在两个图形的相交区域内。故正确答案为B。</p><h2 id="标记线条" tabindex="-1">标记线条 <a class="header-anchor" href="#标记线条" aria-label="Permalink to &quot;标记线条&quot;">​</a></h2><p>【线上：功能元素标记在某条线上。 交点：功能元素标记在两条或多条线的交点上。】</p><p>例题：把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src="'+l+'" alt=""></p><p>A.①④⑥，②③⑤</p><p>B.①②③，④⑤⑥</p><p>C.①⑤⑥，②③④</p><p>D.①③⑤，②④⑥</p><p>解析：考查标记元素的位置；观察小黑点在图形中的位置发现：①③⑤图形中小黑点在线上，②④⑥图形中小黑点在交点上。即①③⑤一组，②④⑥一组。故正确答案为D。</p><h1 id="解题策略" tabindex="-1">解题策略 <a class="header-anchor" href="#解题策略" aria-label="Permalink to &quot;解题策略&quot;">​</a></h1><p><img src="'+c+'" alt=""></p><ol><li>**观察细节：**仔细观察功能元素在图形中的具体位置、注意功能元素的数量及其分布。</li><li>**寻找规律：**观察功能元素在不同图形中的变化规律、找出所有图形中的共性特征或模式。</li><li>**验证假设：**根据观察结果提出初步假设、将假设应用于其他图形，验证其正确性。</li></ol><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p><strong>例题1：把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</strong></p><p><img src="'+_+'" alt=""></p><p>A.①③⑤，②④⑥</p><p>B.①②⑤，③④⑥</p><p>C.①④⑤，②③⑥</p><p>D.①③④，②⑤⑥</p><p>解析：考查标记元素的之间位置关系。每个图形都包含两个箭头，①④⑤两个箭头是垂直关系，②③⑥两个箭头都是平行关系。故正确答案为 C。</p><p><strong>例题2：把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</strong></p><p><img src="'+d+'" alt=""></p><p>A.①②⑤，③④⑥</p><p>B.①③⑥，②④⑤</p><p>C.①③④，②⑤⑥</p><p>D.①②④，③⑤⑥</p><p>解析：考查标记元素标记边的长短；图①③⑥中小半圆是在多边形的最短边上，图②④⑤中小半圆是在多边形的最长边上。即图①③⑥一组，图②④⑤一组。故正确答案为B。</p><p><strong>例题3：把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</strong></p><p><img src="'+g+'" alt=""></p><p>A.①③⑥，②④⑤</p><p>B.①②⑤，③④⑥</p><p>C.①③④，②⑤⑥</p><p>D.①④⑤，②③⑥</p><p>解析：考查标记元素所在空间；观察发现，已知每组图形均有两个小黑点，有的两个小黑点可以连通在一起，有的在两个空间内。在①③⑥中，两个小黑点不能连通；在②④⑤中，两个小黑点可以连通。故正确答案为A。</p><p><strong>例题4：把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</strong></p><p><img src="'+m+'" alt=""></p><p>A.①③④，②⑤⑥</p><p>B.①②⑤，③④⑥</p><p>C.①③⑥，②④⑤</p><p>D.①④⑤，②③⑥</p><p>解析：考查标记元素标记面的大小；每个图形中均含有相同的元素三角形和圆，且六个图形均被分成了两个大小不同的面。①③④中三角形处于图形面积较大部分，圆处于面积较小部分，②⑤⑥中三角形处于面积较小部分，圆处于面积较大部分。故正确答案为A。</p>',72)])])}const y=p(h,[["render",b]]);export{z as __pageData,y as default};
